script.source:
if(ctx['meta_keywords'] != null){
  ArrayList commonKeywords = ['Archives', 'Nethys', 'Wiki', 'Archives of Nethys', 'Pathfinder', 'Official', 'AoN', 'AoNPRD', 'PRD', 'PFSRD', '2E', '2nd Edition'];
  ArrayList meta_keywords = ctx['meta_keywords'];
  meta_keywords.removeAll(commonKeywords);
  ctx['meta_keywords'] = meta_keywords;
}

if (ctx["body_content"] != null) {
  def m = /Price (\d[\d,]*(?:\.\d+)?) (gp|sp|cp|pp)(?:, (\d[\d,]*(?:\.\d+)?) (gp|sp|cp|pp))?(?:, (\d[\d,]*(?:\.\d+)?) (gp|sp|cp|pp))?/.matcher(ctx["body_content"]);
  if (m.find()) {
    double total = 0;
    String n1 = m.group(1).replace(",", "");
    String d1 = m.group(2);
    double v1 = Double.parseDouble(n1);
    if (d1.equals("pp")) total += v1 * 10;
    else if (d1.equals("gp")) total += v1;
    else if (d1.equals("sp")) total += v1 / 10.0;
    else if (d1.equals("cp")) total += v1 / 100.0;
    if (m.group(3) != null) {
      String n2 = m.group(3).replace(",", "");
      String d2 = m.group(4);
      double v2 = Double.parseDouble(n2);
      if (d2.equals("pp")) total += v2 * 10;
      else if (d2.equals("gp")) total += v2;
      else if (d2.equals("sp")) total += v2 / 10.0;
      else if (d2.equals("cp")) total += v2 / 100.0;
    }
    if (m.group(5) != null) {
      String n3 = m.group(5).replace(",", "");
      String d3 = m.group(6);
      double v3 = Double.parseDouble(n3);
      if (d3.equals("pp")) total += v3 * 10;
      else if (d3.equals("gp")) total += v3;
      else if (d3.equals("sp")) total += v3 / 10.0;
      else if (d3.equals("cp")) total += v3 / 100.0;
    }
    ctx["price_gp"] = total;
  }
}

// fix saves
if (ctx['save']!=null){
    String origSaveText = ctx['save'];
    if (origSaveText.contains("Will")){
        ctx['save'] = "Will";
    } else if (origSaveText.contains("Fortitude")){
        ctx['save'] = "Fortitude";
    } else if (origSaveText.contains("Reflex")){
        ctx['save'] = "Reflex";
    }
}

// fix components
if (ctx['casting_components']!=null){
    List components = [];
    String componentText = ctx['casting_components'];
    if (componentText.contains("verbal")){
        components.add("verbal");
    }
    if (componentText.contains("somatic")){
        components.add("somatic");
    }
    if (componentText.contains("material")){
        components.add("material")
    }
    ctx["casting_components"] = components;
}

// correct missing spell subtitles
if (ctx['spell_level'] != null && (ctx['subtitle'] == null || ctx['subtitle'] == "")){
    if(ctx['is_spell'] != null){
        ctx['subtitle'] = "Spell "+ctx['spell_level'];
        ctx['spell_type'] = "spell";
    } else if (ctx['is_cantrip'] != null){
        ctx['subtitle'] = "Cantrip "+ctx['spell_level'];
        ctx['spell_type'] = "cantrip";
    } else if (ctx['is_focus'] != null){
        ctx['subtitle'] = "Focus "+ctx['spell_level'];
        ctx['spell_type'] = 'focus spell';
    } else if (ctx['is_ritual'] != null){
        ctx['subtitle'] = "Ritual "+ctx['spell_level'];
        ctx['spell_type'] = 'ritual';
    }
}

// join spell_list into traditions
if (ctx['traditions'] != null && ctx['spell_list'] != null){
    for(String s: ctx['spell_list']){
        ctx['traditions'].add(s)
    }
}

if (ctx['spell_level'] != null) {
  try {
    int lvl = Integer.parseInt(ctx['spell_level'].trim());
    if (lvl >= 1 && lvl <= 10) {
      ctx['spell_level_bucket'] = 'Level ' + lvl;
    }
  } catch (Exception e) {}
}

if (ctx['feat_level'] != null) {
  try {
    int lvl = Integer.parseInt(ctx['feat_level'].trim());
    if (lvl >= 1 && lvl <= 20) {
      int lo = ((lvl - 1) / 2) * 2 + 1;
      int hi = lo + 1;
      ctx['feat_level_bucket'] = 'Levels ' + lo + '–' + hi;
    }
  } catch (Exception e) {}
}

if (ctx['item_level'] != null) {
  try {
    int lvl = Integer.parseInt(ctx['item_level'].trim());
    if (lvl == 0) {
      ctx['item_level_bucket'] = 'Level 0';
    } else if (lvl >= 1 && lvl <= 20) {
      int lo = ((lvl - 1) / 2) * 2 + 1;
      int hi = lo + 1;
      ctx['item_level_bucket'] = 'Levels ' + lo + '–' + hi;
    } else if (lvl >= 21) {
      ctx['item_level_bucket'] = 'Level 21+';
    }
  } catch (Exception e) {}
}

if (ctx['creature_level'] != null) {
  try {
    int lvl = Integer.parseInt(ctx['creature_level'].trim());
    if (lvl <= 0) {
      ctx['creature_level_bucket'] = 'Level -1 to 0';
    } else if (lvl <= 4) {
      ctx['creature_level_bucket'] = 'Levels 1–4';
    } else if (lvl <= 8) {
      ctx['creature_level_bucket'] = 'Levels 5–8';
    } else if (lvl <= 12) {
      ctx['creature_level_bucket'] = 'Levels 9–12';
    } else if (lvl <= 16) {
      ctx['creature_level_bucket'] = 'Levels 13–16';
    } else if (lvl <= 21) {
      ctx['creature_level_bucket'] = 'Levels 17–21';
    } else {
      ctx['creature_level_bucket'] = 'Level 22+';
    }
  } catch (Exception e) {}
}
